#include <stdio.h>

int average(int total, int count) {
    if (count <= 0) {
        return -1;
    }
    return total / count;
}

int main(void) {
    int fish[3] = { {a}, {b}, {c} };
    int total = fish[0] + fish[1] + fish[2];
    int avg = average(total, 3);
    printf("平均一碗 %d 条\n", avg);
    avg = average(total, 0);
    if (avg < 0) {
        printf("这组数不对，本喵算不出来喵\n");
    }
    return 0;
}
